pub fn repeat(text: &str, times: i64) -> String {
    let mut out = String::from("");
    let mut i: i64 = 0;
    while i < times {
        out += text;
        i += 1;
    }
    return out;
}

pub fn frame(text: &str) -> String {
    let line = repeat("-", text.len() as i64 + 4);
    return format!("{}\n| {} |\n{}", line, text, line);
}

pub fn banner(title: &str) -> String {
    return frame(title);
}

fn main() {
    let title = String::from("php2rust");
    let r#box = banner(&title);
    print!("{}", r#box);
    print!("\n");
    let mut csv = String::from("");
    let items = vec![String::from("a"), String::from("b"), String::from("c")];
    for (k, item) in (0_i64..).zip(items) {
        if k > 0 {
            csv += ",";
        }
        csv += &item;
    }
    print!("{}", csv);
    print!(" ");
    print!("{}", csv.len() as i64);
    print!("\n");
    print!("{}", frame(&csv));
    print!("\n");
    print!("{}", csv);
    print!(" ");
    print!("{}", title);
    print!("\n");
}
